            if a1 - a0 >= 3:
                for off in range(a1 - a0):
                    ra, rb = a0 + off, b0 + off
                    rowa, rowb = grid[ra], grid[rb]
                    def lead(row):
                        first = next((i for i, v in enumerate(row) if v == foreground), None)
